// Comparison-only output. Never used as production geometry or to verify printed values.
const ns='http://www.w3.org/2000/svg';
const parse=s=>{let d=new DOMParser().parseFromString(s,'image/svg+xml');if(d.querySelector('parsererror')||d.documentElement.localName!=='svg')throw Error('גיליון לא תקין');return d;};
const selector='text,line,path,polygon,polyline,circle,ellipse,rect';
function items(root){return [...root.querySelectorAll(selector)].filter(n=>!n.closest('defs,style,clipPath,[data-title-block]')&&!(n.localName==='rect'&&(n.getAttribute('fill')==='white'||n.getAttribute('class')==='border'&&n.getAttribute('x')==='7')));}
function attributes(n){return [...n.attributes].filter(a=>!['data-review-edit','data-dim-ref'].includes(a.name)).map(a=>[a.name,a.value]).sort((a,b)=>a[0].localeCompare(b[0]));}
function signature(n){let ancestors=[];for(let p=n.parentElement;p&&p.localName!=='svg';p=p.parentElement)ancestors.unshift([p.localName,attributes(p)]);return JSON.stringify([ancestors,n.localName,attributes(n),n.textContent,[...n.querySelectorAll('tspan')].map(attributes)]);}
function paint(n,removed){const color='#b91c1c';n.setAttribute('data-diff',removed?'removed':'added');if(n.localName==='text'){n.style.setProperty('fill',color,'important');for(let t of n.querySelectorAll('tspan'))t.style.setProperty('fill',color,'important');if(removed)n.style.setProperty('text-decoration','line-through');}else{n.style.setProperty('stroke',color,'important');n.style.setProperty('stroke-width','.32','important');if(removed){n.style.setProperty('fill','none','important');n.style.setProperty('stroke-dasharray','2 1','important');}}if(removed)n.style.setProperty('opacity','.62');}
export function compareSheets(previous,current){const old=parse(previous),now=parse(current),a=old.documentElement,b=now.documentElement;if(a.getAttribute('viewBox')!==b.getAttribute('viewBox'))return {compatible:false,added:0,removed:0,svg:null};let pool=new Map;for(let n of items(a)){let k=signature(n);if(!pool.has(k))pool.set(k,[]);pool.get(k).push(n);}let added=0,removed=0;for(let n of items(b)){let q=pool.get(signature(n));if(q?.length)q.pop();else{paint(n,false);added++;}}// Preserve original group transforms; clipping references are deliberately not overlaid if definitions differ.
 const defsSame=[...a.querySelectorAll('defs')].map(n=>n.outerHTML).join('')===[...b.querySelectorAll('defs')].map(n=>n.outerHTML).join('');let overlay=now.createElementNS(ns,'g');overlay.setAttribute('data-diff-overlay','true');let omitted=0;for(let q of pool.values())for(let n of q){removed++;let p=n.parentElement,chain=[];while(p&&p!==a){chain.unshift(p);p=p.parentElement;}if(!defsSame&&(n.hasAttribute('clip-path')||chain.some(g=>g.hasAttribute('clip-path')))){omitted++;continue;}let target=overlay;for(let p of chain){let copy=now.importNode(p,false);target.append(copy);target=copy;}let c=now.importNode(n,true);paint(c,true);target.append(c);}b.append(overlay);b.setAttribute('data-review-comparison','true');return {compatible:true,added,removed,omitted,svg:new XMLSerializer().serializeToString(b)};}
